package com.fream.back.domain.order.entity;

import java.util.*;

/**
 * 주문 상태를 정의하는 Enum
 */
public enum OrderStatus {
    PENDING_PAYMENT, // 결제 대기
    PAYMENT_COMPLETED, // 결제 완료
    PREPARING, // 상품 준비 중
    IN_WAREHOUSE, // 창고 보관 중
    SHIPMENT_STARTED, // 배송 시작
    IN_TRANSIT, // 배송 중
    COMPLETED, // 배송 완료
    REFUND_REQUESTED, // 환불 대기
    REFUNDED; // 환불 완료

    // 각 상태에서 전이 가능한 다음 상태들을 정의
